"""Automated news briefings generated by the AI newsdesk.

The service produces two briefings (code & tech, cybersecurity) and
enforces a cross-restart cooldown so a redeploy never spams the channels.
Adapters deliver the text to their own news surfaces.
"""

from __future__ import annotations

import logging
import time
from typing import Literal

from xesxor.core.database import Database
from xesxor.core.services.ai import AIService

logger = logging.getLogger(__name__)

COOLDOWN_KEY = "last_news_post"
COOLDOWN_SECONDS = 7_000
MAX_POST_CHARS = 1500

NewsKind = Literal["coding", "cyber"]

NEWS_STYLE_RULES = (
    "STRICT RULES:\n"
    "- Report ONLY real, well-known technologies, companies, releases, and industry trends.\n"
    "- NEVER invent CVE IDs, statistics, dates, quotes, or product names. "
    "Never use placeholders like 202X or XXXX.\n"
    "- Keep it under 900 characters total. Clean, professional, catchy.\n"
    "- Vary the topics every edition; never repeat a previous headline.\n\n"
    "FORMAT EXACTLY:\n"
    "{catchy headline, max 8 words}\n"
    "> {one-sentence hook}\n"
    "**Top stories**\n"
    "• **{item}** — {one line}\n"
    "• **{item}** — {one line}\n"
    "• **{item}** — {one line}\n"
    "💡 **Why it matters:** {one line}"
)


class NewsService:
    """AI newsdesk with cooldown gating."""

    def __init__(self, db: Database, ai: AIService) -> None:
        self._db = db
        self._ai = ai

    def due(self) -> bool:
        """True when a new edition should be posted (cooldown elapsed)."""
        raw = self._db.get_meta(COOLDOWN_KEY)
        if raw is None:
            return True
        try:
            return time.time() - float(raw) >= COOLDOWN_SECONDS
        except ValueError:
            return True

    def mark_posted(self) -> None:
        """Record that an edition was just published."""
        self._db.set_meta(COOLDOWN_KEY, str(time.time()))

    async def generate(self, kind: NewsKind) -> str:
        """Generate one briefing for *kind*.

        Returns:
            Briefing text (may be the AI-unavailable notice).
        """
        if kind == "coding":
            prompt = (
                "You are the XESXOR AI newsdesk. Write a real-world coding & technology "
                "news briefing about programming languages, frameworks, developer tools, "
                "open source, cloud, or the software industry.\n" + NEWS_STYLE_RULES
            )
            heading = "🗞️ **XESXOR BRIEFING — CODE & TECH**"
        else:
            prompt = (
                "You are the XESXOR AI newsdesk. Write a real-world cybersecurity news "
                "briefing about actual vulnerabilities, patches, breaches, malware trends, "
                "privacy, or defensive practices.\n" + NEWS_STYLE_RULES
            )
            heading = "🛡️ **XESXOR BRIEFING — CYBERSECURITY**"

        body = (await self._ai.ask(prompt, platform_context="community news channel"))[:MAX_POST_CHARS]
        return f"{heading}\n\n{body}\n\n— *XESXOR AI Newsdesk*"
